class Solution {
  private int[] left, right, cnt;
  private long[] sum;
  private int nodes;

  private int insert(int prev, int lo, int hi, int pos, long value) {
    int cur = ++nodes;
    left[cur] = left[prev];
    right[cur] = right[prev];
    cnt[cur] = cnt[prev] + 1;
    sum[cur] = sum[prev] + value;
    if (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (pos <= mid) left[cur] = insert(left[prev], lo, mid, pos, value);
      else right[cur] = insert(right[prev], mid + 1, hi, pos, value);
    }
    return cur;
  }

  public long[] minOperations(int[] nums, int k, int[][] queries) {
    int n = nums.length;
    long[] v = new long[n];
    for (int i = 0; i < n; i++) v[i] = nums[i] / k;
    long[] sortedVals = v.clone();
    java.util.Arrays.sort(sortedVals);
    int m = 0;
    for (int i = 0; i < n; i++)
      if (i == 0 || sortedVals[i] != sortedVals[i - 1]) sortedVals[m++] = sortedVals[i];
    int[] bad = new int[n + 1];
    for (int i = 1; i < n; i++) bad[i + 1] = bad[i] + (nums[i] % k != nums[i - 1] % k ? 1 : 0);
    int cap = n * 18 + 5;
    left = new int[cap];
    right = new int[cap];
    cnt = new int[cap];
    sum = new long[cap];
    int[] root = new int[n + 1];
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) {
      int pos = java.util.Arrays.binarySearch(sortedVals, 0, m, v[i]);
      root[i + 1] = insert(root[i], 0, m - 1, pos, v[i]);
      pre[i + 1] = pre[i] + v[i];
    }
    long[] ans = new long[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int l = queries[qi][0], r = queries[qi][1];
      if (bad[r + 1] - bad[l + 1] != 0) {
        ans[qi] = -1;
        continue;
      }
      int len = r - l + 1, kth = (len + 1) / 2;
      int a = root[r + 1], b = root[l];
      int lo = 0, hi = m - 1, rem = kth;
      long acc = 0;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        int cl = cnt[left[a]] - cnt[left[b]];
        if (rem <= cl) {
          a = left[a];
          b = left[b];
          hi = mid;
        } else {
          rem -= cl;
          acc += sum[left[a]] - sum[left[b]];
          a = right[a];
          b = right[b];
          lo = mid + 1;
        }
      }
      long med = sortedVals[lo];
      long smallest = acc + (long) rem * med;
      long total = pre[r + 1] - pre[l];
      ans[qi] = med * kth - smallest + (total - smallest) - med * (len - kth);
    }
    return ans;
  }
}
